IF NOT EXISTS(SELECT 1 FROM sys.schemas WHERE name='auth') EXEC('CREATE SCHEMA auth');
GO
CREATE TABLE auth.Users(UserId BIGINT IDENTITY PRIMARY KEY,FullName NVARCHAR(120) NOT NULL,Email NVARCHAR(254) NOT NULL,MobileNumber NVARCHAR(30) NULL,PasswordHash NVARCHAR(500) NOT NULL,IsActive BIT NOT NULL DEFAULT(1),IsEmailVerified BIT NOT NULL DEFAULT(0),IsDeleted BIT NOT NULL DEFAULT(0),CreatedAtUtc DATETIME2(3) NOT NULL DEFAULT SYSUTCDATETIME(),UpdatedAtUtc DATETIME2(3) NULL);
GO
CREATE UNIQUE INDEX UX_AuthUsers_Email ON auth.Users(Email) WHERE IsDeleted=0;
CREATE UNIQUE INDEX UX_AuthUsers_Mobile ON auth.Users(MobileNumber) WHERE MobileNumber IS NOT NULL AND IsDeleted=0;
GO
CREATE TABLE auth.Roles(RoleId INT IDENTITY PRIMARY KEY,RoleName NVARCHAR(50) NOT NULL UNIQUE);
CREATE TABLE auth.UserRoles(UserId BIGINT NOT NULL,RoleId INT NOT NULL,CONSTRAINT PK_AuthUserRoles PRIMARY KEY(UserId,RoleId),FOREIGN KEY(UserId) REFERENCES auth.Users(UserId),FOREIGN KEY(RoleId) REFERENCES auth.Roles(RoleId));
CREATE TABLE auth.RefreshTokens(RefreshTokenId BIGINT IDENTITY PRIMARY KEY,UserId BIGINT NOT NULL,TokenHash CHAR(64) NOT NULL UNIQUE,ExpiresAtUtc DATETIME2(3) NOT NULL,CreatedAtUtc DATETIME2(3) NOT NULL,RevokedAtUtc DATETIME2(3) NULL,ReplacedByTokenHash CHAR(64) NULL,FOREIGN KEY(UserId) REFERENCES auth.Users(UserId));
GO
INSERT auth.Roles(RoleName) SELECT v.RoleName FROM(VALUES(N'Owner'),(N'Admin'),(N'Manager'),(N'Cashier'),(N'Kitchen'),(N'Waiter'))v(RoleName) WHERE NOT EXISTS(SELECT 1 FROM auth.Roles r WHERE r.RoleName=v.RoleName);
GO